import assert from "node:assert/strict"
import { readFileSync, readdirSync } from "node:fs"
import { dirname, join } from "node:path"
import { test } from "node:test"
import { fileURLToPath } from "node:url"
import { renderEvidenceBlock, extractEvidenceBlock } from "./lib/evidence-block.mjs"

/**
 * evidence-drift.test.mjs — the guard against the stale-figure class of defect.
 *
 * It reads artifacts/readiness/evidence.json (generated by
 * scripts/collect-evidence.mjs) and asserts that the documented figures match
 * the generated source, and that the audit documents cite that source instead of
 * restating numbers. Deliberately corrupt one value in evidence.json and this
 * test fails; restore it and it passes.
 *
 * These expectations are pinned to the known-good baseline at HEAD dd5c68d2. They
 * are the *guard*, not the documentation: the audit documents cite evidence.json,
 * and this test is what makes a silent rot visible.
 */

const root = join(dirname(fileURLToPath(import.meta.url)), "..")
const evidence = JSON.parse(
  readFileSync(join(root, "artifacts", "readiness", "evidence.json"), "utf8"),
)

// Count migration files using the same rule as check-supabase-migrations.mjs:
// every *.sql in supabase/migrations, including demo_schema_init.sql
const migrationFiles = readdirSync(join(root, "supabase", "migrations"))
  .filter((f) => f.endsWith(".sql"))
  .sort().length

const EXPECTED = {
  gitHead: "dd5c68d276d130f43b3b7516f67f3d7fa58a87b2",
  migrationCount: migrationFiles,
  rlsTests: 21,
  hardeningTests: 74,
  tenancyTests: 59,
  workflowSafetyTests: 60,
  rlsMatrixTests: 10,
}

test("evidence.json records the expected HEAD", () => {
  assert.equal(evidence.git.head, EXPECTED.gitHead,
    "git HEAD has moved past the baseline; regenerate evidence with 'node scripts/collect-evidence.mjs'")
})

test("evidence.json records the expected migration count", () => {
  assert.equal(evidence.migrationCount.count, EXPECTED.migrationCount,
    `migration count in evidence.json (${evidence.migrationCount.count}) does not match supabase/migrations directory (${EXPECTED.migrationCount}); regenerate evidence with 'node scripts/collect-evidence.mjs'`)
})

test("evidence.json records the expected suite test counts", () => {
  assert.equal(evidence.suites["rls-tenant-isolation"].tests, EXPECTED.rlsTests)
  assert.equal(evidence.suites.hardening.tests, EXPECTED.hardeningTests)
  assert.equal(evidence.suites.tenancy.tests, EXPECTED.tenancyTests)
  assert.equal(evidence.suites["workflow-safety"].tests, EXPECTED.workflowSafetyTests)
  assert.equal(evidence.suites["rls-matrix"].tests, EXPECTED.rlsMatrixTests)
})

test("every recorded suite that is expected to pass has exitCode 0", () => {
  // security-gates is deliberately excluded: its banner and exit code are the
  // gate's own output, and this test runs inside that gate — asserting them here
  // would make regeneration circular.
  for (const key of [
    "rls-tenant-isolation",
    "hardening",
    "tenancy",
    "workflow-safety",
    "rls-matrix",
  ]) {
    assert.equal(evidence.suites[key].exitCode, 0, `${key} must exit 0`)
  }
})

test("the audit documents cite the generated evidence source", () => {
  for (const doc of [
    "docs/audits/REMEDIATION_CLOSURE_2026-10-25.md",
    "docs/audits/REMEDIATION_HANDOVER_2026-10-25.md",
  ]) {
    const text = readFileSync(join(root, doc), "utf8")
    assert.match(text, /artifacts\/readiness\/evidence\.json/, `${doc} must cite evidence.json`)
  }
})

test("the audit documents' evidence block matches the generated evidence exactly", () => {
  const block = renderEvidenceBlock(evidence)
  for (const doc of [
    "docs/audits/REMEDIATION_CLOSURE_2026-10-25.md",
    "docs/audits/REMEDIATION_HANDOVER_2026-10-25.md",
  ]) {
    const text = readFileSync(join(root, doc), "utf8")
    const extracted = extractEvidenceBlock(text)
    assert.notEqual(extracted, null, `${doc} must contain the evidence markers`)
    assert.equal(extracted, block, `${doc} evidence block must equal the rendered evidence.json`)
  }
})

// Deliberately NOT policing the audit documents' prose for hard-coded numbers.
// A negative regex over historical prose is what erased the real record of past
// passes ("16 tests at the time", "migrations=4") from §10. The guard against a
// restated *current* count is the two positive tests above: the pinned baseline
// and the requirement that the documents cite the generated evidence source.
